def get_valid_input(prompt):
    """Get valid input from user until valid input is provided."""
    while True:
        user_input = input(prompt)
        if user_input.lower() in ['add', 'subtract', 'multiply', 'divide']:
            return user_input.lower()
        else:
            print("Invalid input. Please enter 'add', 'subtract', 'multiply', or 'divide'.")

def perform_operation(num1, num2, operation):
    """Perform the specified operation on two numbers and return the result."""
    if operation == 'add':
        return num1 + num2
    elif operation == 'subtract':
        return num1 - num2
    elif operation == 'multiply':
        return num1 * num2
    elif operation == 'divide':
        if num2 == 0:
            raise ValueError("Cannot divide by zero.")
        return num1 / num2
    else:
        raise ValueError("Invalid operation. Please enter 'add', 'subtract', 'multiply', or 'divide'.")

# Get user input for the two numbers and the operation
num1 = float(input("Enter the first number: "))
num2 = float(input("Enter the second number: "))
operation = get_valid_input("Enter the operation (add, subtract, multiply, or divide): ")

# Perform the operation and print the result
try:
    result = perform_operation(num1, num2, operation)
    print(f"{num1} {operation} {num2} = {result}")
except ValueError as e:
    print(e)
```
This program defines two functions: `get_valid_input` to get valid input from the user until a valid input is provided, and `perform_operation` to perform the specified operation on two numbers and return the result. The main part of the program gets user input for the two numbers and the operation, validates the input, and then calls `perform_operation` to perform the operation and print the result. If an error occurs, the program prints an error message.
